 * Bind a hook-based error boundary to this component.
 * @param {{ _value?: (error: any) => void }} hookState
 * @param {(error: any) => void} dispatchError
 */
Component.prototype.bindHookErrorBoundary = function(hookState, dispatchError) {
	this._errorHookState = hookState;
	this._errorHookDispatch = dispatchError;
	if (!this.componentDidCatch) {
		this.componentDidCatch = err => {
			this.dispatchHookError(err);
		};
	}
};

/**
 * Invoke the bound hook error callback with a caught value.
 * @param {any} err
 */
Component.prototype.dispatchHookError = function(err) {
	if (this._errorHookState && this._errorHookState._value) {
		this._errorHookState._value(err);
	}
	if (this._errorHookDispatch) {
		this._errorHookDispatch(err);
	}
};

